using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CharacterDevelopmentTests
{
    static WorldSession Start(int otherValor=50,bool enabled=true){var a=NewGameWorldTests.Officer();var b=NewGameWorldTests.Officer("created:other") with{Attributes=new(60,otherValor,70,40){Negotiation=75}};var setup=NewGameWorldTests.Setup([a,b]);return new(NewGameWorld.Create(setup.World,setup.Registered,a.Id,42,developmentPolicy:enabled?CharacterDevelopment.Policy:null));}
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static Intent Train(WorldSession s,DevelopmentSkill skill=DevelopmentSkill.Construction){var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:practice/"+s.Revision,skill);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);return i;}
    [Fact]public void RegisteredFourValuesRemainByteCompatible(){var p=NewGameWorldTests.Officer();var bytes=ContractJson.Write(p);Assert.DoesNotContain("Negotiation",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(ContractJson.Read<RegisteredOfficer>(bytes)));}
    [Fact]public void ExplicitNegotiationSurvivesLibraryCopy(){var p=NewGameWorldTests.Officer() with{Attributes=new(60,50,70,40){Negotiation=81}};var library=new OfficerLibrary(1,[p],[new("group:test","試験",[])]);var copy=NewGameSetup.CopyToGroup(library,p.Id,"group:test","created:copy");Assert.Equal(81,copy.Groups[0].Officers[0].Attributes.Negotiation);Assert.Equal(81,ContractJson.Read<OfficerLibrary>(ContractJson.Write(copy)).Ungrouped[0].Attributes.Negotiation);}
    [Theory][InlineData(-1)][InlineData(101)]public void InvalidNegotiationRejected(int n){var p=NewGameWorldTests.Officer() with{Attributes=new(60,50,70,40){Negotiation=n}};Assert.Throws<InvalidDataException>(()=>{var t=NewGameWorldTests.Setup([p]);NewGameWorld.Create(t.World,t.Registered,p.Id);});}
    [Fact]public void LegacyPolicyDoesNotCreateGrowth(){var s=Start(enabled:false);Assert.Null(s.DiagnosticSnapshot().Development);Assert.Null(s.CharacterCard(s.PlayerControl));Assert.Throws<InvalidDataException>(()=>CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:train",DevelopmentSkill.Tactics));}
    [Fact]public void OtherHiddenValuesDoNotReachCharacterView(){var a=Start(5);var b=Start(95);Assert.Equal(ContractJson.Write(a.CharacterCard(new("created:other"))),ContractJson.Write(b.CharacterCard(new("created:other"))));Assert.All(a.CharacterCard(new("created:other"))!.Abilities,x=>Assert.Null(x.Value));}
    [Fact]public void OwnFiveAbilitiesAndSevenSkillsHaveExactValues(){var s=Start();var v=s.CharacterCard(s.PlayerControl)!;Assert.True(v.Own);Assert.Equal(5,v.Abilities.Length);Assert.Equal(7,v.Skills.Length);Assert.Equal(50,v.Abilities[4].Value);Assert.All(v.Skills,x=>Assert.Equal(0,x.Value));}
    [Theory][InlineData(DevelopmentSkill.Agriculture)][InlineData(DevelopmentSkill.Commerce)][InlineData(DevelopmentSkill.Construction)][InlineData(DevelopmentSkill.Logistics)][InlineData(DevelopmentSkill.Tactics)][InlineData(DevelopmentSkill.IntelligenceGathering)][InlineData(DevelopmentSkill.Etiquette)]
    public void CompletedPracticeCreditsOnlyChosenSkill(DevelopmentSkill skill){var s=Start();var before=s.DiagnosticSnapshot();var i=Train(s,skill);At(s,1802);var w=s.DiagnosticSnapshot();var award=Assert.Single(w.Development!.Awards);Assert.Equal(skill,award.Skill);Assert.Equal(1800,award.Seconds);Assert.Equal(i.Executor,award.Actor);Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(w.Offices));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Development!.Awards);}
    [Fact]public void WaitingAndPartialPracticeHaveNoGrowth(){var s=Start();Train(s);At(s,900);Assert.Empty(s.DiagnosticSnapshot().Development!.Awards);var t=s.DiagnosticSnapshot().Tasks.Single();Assert.Equal(ResultCode.Accepted,s.StopPractice(t.Id,s.Revision).Code);At(s,2000);Assert.Empty(s.DiagnosticSnapshot().Development!.Awards);Assert.Equal(ResultCode.AlreadyAccepted,s.StopPractice(t.Id,s.Revision).Code);}
    [Fact]public void BusyCharacterCannotQueueAnotherPractice(){var s=Start();Train(s);var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:another",DevelopmentSkill.Tactics);Assert.Equal(ResultCode.InvalidInput,s.Submit(i,s.Revision).Code);}
    [Fact]public void PracticeRequiresItsExactDuration(){var s=Start();var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:short",DevelopmentSkill.Tactics) with{WorkSeconds=1};Assert.Equal(ResultCode.InvalidInput,s.Submit(i,s.Revision).Code);}
    [Fact]public void InspectionCreditsOnlyActualTime(){var s=Start();Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:inspect"),s.Revision).Code);At(s,6);var a=Assert.Single(s.DiagnosticSnapshot().Development!.Awards);Assert.Equal(4,a.Seconds);Assert.Equal(DevelopmentSkill.IntelligenceGathering,a.Skill);Assert.All(s.CharacterCard(s.PlayerControl)!.Abilities,v=>Assert.True(v.Experience<10));}
    [Fact]public void ForgedExperienceIsRejected(){var s=Start();Train(s);At(s,1802);var w=s.DiagnosticSnapshot();w.Development!.Awards[0]=w.Development.Awards[0] with{Experience=999999};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingAwardIsRejected(){var s=Start();Train(s);At(s,1802);var w=s.DiagnosticSnapshot();w.Development=w.Development! with{Awards=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void RealGenerationRecoveryPreservesProgressAndFuture(int phase){var s=Start();if(phase>0){Train(s);At(s,phase==1?1:phase==2?900:1802);if(phase==4){Train(s,DevelopmentSkill.Tactics);At(s,2000);Assert.Equal(ResultCode.Accepted,s.StopPractice(s.DiagnosticSnapshot().Tasks.Last().Id,s.Revision).Code);}}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"development-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"development",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("development"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.CharacterCard(s.PlayerControl)),ContractJson.Write(host.Current.CharacterCard(s.PlayerControl)));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"character-development-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"character-development-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+2000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    [Fact]public void RepeatedCompletedPracticeRaisesSkillWithoutGrantingOffice(){var s=Start();for(int n=0;n<6;n++){Train(s);At(s,s.Seconds+1802);}var w=s.DiagnosticSnapshot();Assert.True(s.CharacterCard(s.PlayerControl)!.Skills.Single(x=>x.Name=="普請").Value>=1);Assert.DoesNotContain(w.Offices,x=>x.Subject==s.PlayerControl);Assert.Empty(w.Debts);Assert.Empty(w.Transfers);}
    [Fact]public void DailyTrainingCreditIsBounded(){var s=Start();for(int n=0;n<18;n++){Train(s);At(s,s.Seconds+1802);}Assert.Equal(28800,s.DiagnosticSnapshot().Development!.Awards.Sum(a=>a.Seconds));Assert.Equal(0,s.DiagnosticSnapshot().Development!.Awards.Last().Experience);}
    [Fact]public void HistoricalInitialValuesAreStableAndLabelledProvisional(){var scenario=NewGameWorld.Scenario();WorldSession Make()=>new(NewGameWorld.Create(scenario,[],"person:nobunaga",42,developmentPolicy:CharacterDevelopment.Policy));var a=Make();var b=Make();Assert.Equal(ContractJson.Write(a.CharacterCard(a.PlayerControl)),ContractJson.Write(b.CharacterCard(b.PlayerControl)));Assert.All(a.CharacterCard(a.PlayerControl)!.Abilities,v=>Assert.Contains("史実評価ではありません",v.Source));}
    [Fact]public void RestMustFinishOrBeCancelledBeforePractice(){var setup=NewGameWorldTests.Setup();var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:test",inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:PersonalLife.Policy,developmentPolicy:CharacterDevelopment.Policy));var site=s.PersonalLifeView()!.Site!.Value;Assert.Equal(ResultCode.Accepted,s.ManageLife(new(new("request:free-rest"),LifeAction.RestOutside,site),s.PlayerControl,s.Revision).Code);var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:rest-training",DevelopmentSkill.Tactics);Assert.Equal(ResultCode.InvalidInput,s.Submit(i,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Development!.Awards);}
    [Fact]public void ActualReportedWorkGivesDatedEvidenceNotTrueRatings(){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:NewGameWork.Policy,developmentPolicy:CharacterDevelopment.Policy));var input=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:development-work");Assert.Equal(ResultCode.Accepted,s.Submit(input,s.Revision).Code);At(s,1);var task=s.DiagnosticSnapshot().Tasks.Last();var mid=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id.Value.EndsWith("/order")).Id;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,mid,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.Assent(task.Id,s.PlayerControl,true,s.Revision).Code);At(s,8);var w=s.DiagnosticSnapshot();var view=CharacterDevelopment.View(w,input.Actor,s.PlayerControl)!;Assert.All(view.Abilities,x=>Assert.Null(x.Value));var info=view.Skills.Single(x=>x.Name=="情報");Assert.NotNull(info.ObservedAt);Assert.Contains("点検完了",info.Source);Assert.Null(info.Value);var before=ContractJson.Write(view);w.Development!.Awards[0]=w.Development.Awards[0] with{Experience=999999};Assert.Equal(before,ContractJson.Write(CharacterDevelopment.View(w,input.Actor,s.PlayerControl)));}

    [Fact]public void PracticeCanBeWithdrawnBeforeItsOrderArrives(){var s=Start();Train(s);var t=s.DiagnosticSnapshot().Tasks.Single();Assert.Equal(ResultCode.Accepted,s.StopPractice(t.Id,s.Revision).Code);At(s,2000);Assert.Empty(s.DiagnosticSnapshot().Development!.Awards);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);}
}
